cd /root/autodl-tmp/tax_error_inject_agent/artifacts/training_dynamics_v2 && python3 << 'PYEOF'
import json, math

def mean(xs):
    return sum(xs)/len(xs) if xs else 0
def std(xs):
    if len(xs)<2: return 0
    m=mean(xs)
    return math.sqrt(sum((x-m)**2 for x in xs)/(len(xs)-1))

files = ['vanilla_full.json', 'taxei_full.json', 'random_full.json', 
         'taxei_inject10.json', 'taxei_inject25.json', 'taxei_inject50.json']

for f in files:
    d = json.load(open(f))
    print(f'===== {f} =====')
    print(f'checkpoint: {d.get("checkpoint","N/A").split("/")[-1]}')
    print(f'summary: {json.dumps(d.get("summary",{}), indent=2)}')

    op = d.get("operator_summary", {})
    if op:
        print(f'operator_summary: {json.dumps(op, indent=2)}')

    samples = d.get("samples", [])
    print(f'total samples: {len(samples)}')

    if samples:
        clean = [s["loss"] for s in samples if s["subset"] == "clean"]
        injected = [s["loss"] for s in samples if s["subset"] == "injected"]
        print(f'  clean: n={len(clean)}, mean={mean(clean):.4f}, std={std(clean):.4f}')
        if injected:
            print(f'  injected: n={len(injected)}, mean={mean(injected):.4f}, std={std(injected):.4f}')
            print(f'  gap (inj-clean): {mean(injected)-mean(clean):.4f}')

        ops = {}
        for s in samples:
            et = s.get("error_type")
            if et:
                ops.setdefault(et, []).append(s["loss"])
        if ops:
            print(f'  per-operator losses:')
            for op_name, losses in sorted(ops.items()):
                print(f'    {op_name}: n={len(losses)}, mean={mean(losses):.4f}, std={std(losses):.4f}')
    print()
PYEOF

